                               const struct nf_hook_state *state)
{
    u8 proto = ip_hdr(skb)->protocol;

    /*
     * The pkt_counts array is indexed by IP protocol number.
     * The array size is MAX_PROTO (64), but proto can be 0-255.
     * We must ensure the index is within bounds.
     * Protocols greater than or equal to MAX_PROTO will be counted
     * under the MAX_PROTO-1 index (the last valid index).
     */
    if (proto >= MAX_PROTO) {
        proto = MAX_PROTO - 1;
    }
    per_cpu(pkt_counts, smp_processor_id())[proto]++;
    return NF_ACCEPT;
}
